// Thread-local storage duration declarations:

// 1. Namespace scope thread_local
thread_local int tls_counter = 0;

// 2. Class static member (C++11)
class Widget {
    static thread_local int thread_id;
};
thread_local int Widget::thread_id = 0;

// 3. Function-local thread_local
void foo() {
    thread_local int call_count = 0;  // Per-thread, persists across calls
    ++call_count;
}

// 4. Combined with static (namespace scope, redundant but allowed)
static thread_local int file_local_tls = 0;

code_example:
#include <iostream>
#include <thread>
#include <vector>
#include <chrono>

// Global thread_local variable - each thread gets its own copy
thread_local int thread_id = 0;
thread_local int thread_call_count = 0;

class ThreadCounter {
public:
    ThreadCounter() {
        std::cout << "ThreadCounter constructed in thread " 
                  << std::this_thread::get_id() << "\n";
    }
    ~ThreadCounter() {
        std::cout << "ThreadCounter destroyed in thread " 
                  << std::this_thread::get_id() << "\n";
    }

    // Thread-local static member
    static thread_local int instance_count;
};

thread_local int ThreadCounter::instance_count = 0;

void worker_function(int id) {
    // Each thread gets its own copy of these variables
    thread_id = id;

    // Function-local thread_local - initialized once per thread
    thread_local ThreadCounter counter;
    ThreadCounter::instance_count++;

    // Simulate work
    for (int i = 0; i < 3; ++i) {
        thread_call_count++;
        std::cout << "Thread " << thread_id 
                  << ": call_count=" << thread_call_count
                  << ", instance_count=" << ThreadCounter::instance_count
                  << "\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}  // ThreadCounter destroyed when thread exits

int main() {
    std::cout << "=== Thread Storage Duration Demo ===\n\n";

    // Main thread has its own copy
    thread_id = 999;
    std::cout << "Main thread ID: " << thread_id << "\n\n";

    // Create multiple threads
    std::vector<std::thread> threads;
    for (int i = 1; i <= 3; ++i) {
        threads.emplace_back(worker_function, i);
    }

    // Wait for all threads
    for (auto& t : threads) {
        t.join();
    }

    // Main thread's copy is unchanged
    std::cout << "\nMain thread ID still: " << thread_id << "\n";
    std::cout << "Main thread call_count: " << thread_call_count << "\n";

    return 0;
}

// Output shows each thread has independent copies:
// === Thread Storage Duration Demo ===
//
// Main thread ID: 999
//
// ThreadCounter constructed in thread 0x...
// ThreadCounter constructed in thread 0x...
// ThreadCounter constructed in thread 0x...
// Thread 1: call_count=1, instance_count=1
// Thread 2: call_count=1, instance_count=1
// Thread 3: call_count=1, instance_count=1
// Thread 1: call_count=2, instance_count=1
// ...
// ThreadCounter destroyed in thread 0x...
// ThreadCounter destroyed in thread 0x...
// ThreadCounter destroyed in thread 0x...
//
// Main thread ID still: 999
// Main thread call_count: 0
